const item = $input.item;
const data = item.json;

const possibleFields = [
  data.text, data.textPlain, data.body,
  data.message, data.content, data.html, data.textHtml,
];

let rawText = possibleFields.find(v => typeof v === 'string' && v.trim()) || '';

if (!rawText) {
  const jsonText = JSON.stringify(data, null, 2);
  const bodyMatch =
    jsonText.match(/"text"\s*:\s*"([\s\S]*?)"/i) ||
    jsonText.match(/"textPlain"\s*:\s*"([\s\S]*?)"/i) ||
    jsonText.match(/"body"\s*:\s*"([\s\S]*?)"/i) ||
    jsonText.match(/"html"\s*:\s*"([\s\S]*?)"/i);
  rawText = bodyMatch ? bodyMatch[1] : '';
}

rawText = rawText
  .replace(/\\r\\n/g, '\n').replace(/\\n/g, '\n')
  .replace(/\\t/g, ' ').replace(/\\"/g, '"');

rawText = rawText
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n')
  .replace(/<\/div>/gi, '\n').replace(/<[^>]*>/g, ' ')
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&')
  .replace(/\r/g, '').replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n').trim();

// Стандартні маркери підпису — без назви конкретної компанії
const signatureMarkers = [
  'З повагою,', 'З повагою ', 'С уважением',
  'Best regards', 'Kind regards', 'Regards,',
  'Тел.:', 'Телефон:', 'Phone:', 'Mobile:',
];

let cleanText = rawText;
for (const marker of signatureMarkers) {
  const index = cleanText.indexOf(marker);
  if (index !== -1) {
    cleanText = cleanText.slice(0, index).trim();
    break;
  }
}

return [{
  json: { ...data, email_text_raw: rawText, email_text: cleanText },
  binary: item.binary,
}];

const job_number    = $('Edit Fields').first().json.job_number    || '';
const email_subject = $('Edit Fields').first().json.email_subject || '';
const email_from    = $('Edit Fields').first().json.email_from    || '';
const email_text    = $('Extract clean email text').first().json.email_text || '';

// AI extracted fields
const ai = $('Parse Claude Response').first().json;
const client_name      = (ai.client_name      || '').trim();
const invoice_date     = (ai.invoice_date      || '').trim();
const container_number = (ai.container_number  || '').trim();
const bl_number        = (ai.bl_number         || '').trim();
const awb_number       = (ai.awb_number        || '').trim();
const cmr_number       = (ai.cmr_number        || '').trim();
const cmr_date         = (ai.cmr_date          || '').trim();
const route            = (ai.route             || '').trim();
const border_total_raw = Number(ai.border_total    || 0);
const insurance_amount = Number(ai.insurance_amount|| 0);

// Страхування ЗАВЖДИ включається до загальної суми до кордону
const border_total = border_total_raw + insurance_amount;

// Clean service name — safety net
function cleanServiceName(name) {
  return name
    .trim()
    .replace(/^відшкодування\s+(витрат\s+)?за\s+/i, '')
    .replace(/^відшкодування\s+вартості\s+/i, '')
    .replace(/^компенсація\s+вартості\s+/i, '')
    .replace(/^компенсація\s+/i, '')
    .replace(/\s+(по|за)\s+маршрут\w*\s+.*/i, '')
    // [\/\.] без "?" — тільки "м." або "м/", не "м" у середині слова
    .replace(/\s+м[\/\.]\s*[\wа-яіїєґ\-]+(?:[\s,].*)?$/i, '')
    .trim();
}

const rawServices = (ai.border_services_names || '').trim();
let border_services_names = rawServices
  .split(',')
  .map(s => cleanServiceName(s))
  .filter(s => s.length > 0)
  .join(', ');

// Додати страхування до переліку послуг якщо є
if (insurance_amount > 0) {
  border_services_names = border_services_names
    ? border_services_names + ', страхування вантажу'
    : 'страхування вантажу';
}

// Date helpers
const MONTHS = ['','січня','лютого','березня','квітня','травня','червня',
                'липня','серпня','вересня','жовтня','листопада','грудня'];
const MONTHS_NUM = ['','01','02','03','04','05','06','07','08','09','10','11','12'];

function todayUa() {
  const now = new Date();
  return `${now.getDate()} ${MONTHS[now.getMonth()+1]} ${now.getFullYear()} р.`;
}
function dateToFilename(dateStr='') {
  const m = dateStr.match(/(\d{1,2})\s+([\wа-яіїєґ]+)\s+(\d{4})/i);
  if (!m) return dateStr.replace(/\s*р\.$/, '').trim();
  const d  = String(m[1]).padStart(2,'0');
  const mo = MONTHS.findIndex(x => x.toLowerCase() === m[2].toLowerCase());
  const moStr = mo > 0 ? MONTHS_NUM[mo] : '??';
  return `${d}.${moStr}.${m[3]}`;
}

const date = invoice_date || todayUa();

// Документи в дужках після "вантажу"
const docParts = [];
if (container_number) docParts.push(`контейнер ${container_number}`);
if (bl_number)        docParts.push(`коносамент ${bl_number}`);
if (awb_number)       docParts.push(`авіанакладна ${awb_number}`);
if (cmr_number && cmr_date) docParts.push(`CMR ${cmr_number} від ${cmr_date}`);
else if (cmr_number)        docParts.push(`CMR ${cmr_number}`);

const docsInParens = docParts.length > 0 ? ` (${docParts.join(', ')})` : '';
const transport_documents_phrase = docParts.join(', ');

// Форматування суми (вже з страхуванням)
const border_amount = Number(border_total || 0)
  .toLocaleString('uk-UA', {minimumFractionDigits:2, maximumFractionDigits:2});

// Страхування включено в суму — окремий рядок показуємо тільки якщо НЕ було страхування
const insurance_phrase = insurance_amount > 0
  ? ''
  : 'Страхування вантажу не проводилось.';

// Основний текст
const routeText  = route                 || '[МАРШРУТ ПОТРІБНО ПЕРЕВІРИТИ]';
const svcText    = border_services_names || '[ПЕРЕЛІК ПОСЛУГ ПОТРІБНО ПЕРЕВІРИТИ]';
const amountText = border_total > 0      ? border_amount : '[СУМУ ПОТРІБНО ПЕРЕВІРИТИ]';

const main_text =
  `Повідомляємо, що вартість міжнародного перевезення вантажу${docsInParens} ` +
  `по маршруту ${routeText}, яка включає ${svcText}, складає ${amountText} гривень.`;

// Ім'я файлу
const safeName = (s) => s.replace(/[\/\\:*?"<>|]/g, '').replace(/\s+/g, ' ').trim();
const dovidka_filename = `Довідка_${safeName(client_name)}_${safeName(route)}_${dateToFilename(date)}.docx`;

const warnings = [];
if (!route)                  warnings.push('Маршрут не визначено AI.');
if (!border_services_names)  warnings.push('Перелік послуг не визначено AI.');
if (!border_total)           warnings.push('Сума до кордону = 0.');

return [{
  json: {
    job_number, email_subject, email_from, email_text,
    date, client_name, container_number,
    bl_number, awb_number, cmr_number, cmr_date,
    transport_documents_phrase, route,
    border_services_names, border_total, border_amount,
    insurance_amount, insurance_phrase,
    main_text, dovidka_filename, warnings,
  }
}];

const docId = $input.item.json.id;
const date = $('Prepare document data').item.json.date;
const main_text = $('Prepare document data').item.json.main_text;
const insurance_phrase = $('Prepare document data').item.json.insurance_phrase || '';

const requestBody = JSON.stringify({
  requests: [
    { replaceAllText: { containsText: { text: '{{date}}', matchCase: true }, replaceText: date } },
    { replaceAllText: { containsText: { text: '{{main_text}}', matchCase: true }, replaceText: main_text } },
    { replaceAllText: { containsText: { text: '{{insurance_phrase}}', matchCase: true }, replaceText: insurance_phrase } }
  ]
});

return [{ json: { id: docId, body_json_string: requestBody } }];

const binary = $input.item.binary.dovidka_docx;
const filename = $('Prepare document data').item.json.dovidka_filename || 'Довідка.docx';
return [{
  json: $input.item.json,
  binary: {
    dovidka_docx: {
      ...binary,
      fileName: filename
    }
  }
}];

const response = $input.item.json;
const text = response.content?.[0]?.text || '';

// Знайти JSON у відповіді
const jsonMatch = text.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  throw new Error('Claude не повернув JSON. Відповідь: ' + text.substring(0, 200));
}

let extracted;
try {
  extracted = JSON.parse(jsonMatch[0]);
} catch(e) {
  throw new Error('Помилка парсингу JSON: ' + e.message + '\n' + jsonMatch[0].substring(0, 200));
}

// Передати binary (PDF) далі
return [{
  json: extracted,
  binary: $('Extract invoice text').first().binary
}];

const item = $input.item;
const binary = item.binary || {};

// Знайти перше PDF вкладення серед усіх attachment_*
let pdfKey = null;
for (const [key, val] of Object.entries(binary)) {
  if (
    val.mimeType === 'application/pdf' ||
    (val.fileName && val.fileName.toLowerCase().endsWith('.pdf'))
  ) {
    pdfKey = key;
    break;
  }
}

if (!pdfKey) {
  throw new Error(
    'PDF вкладення не знайдено. Прикріпіть рахунок у форматі PDF до листа.'
  );
}

// Копіюємо знайдений PDF під стандартний ключ 'invoice_pdf'
return [{
  json: item.json,
  binary: {
    ...binary,
    invoice_pdf: binary[pdfKey]
  }
}];

